exercise.solution:
const INITIAL_TICKETS = [
  { id: 1, title: "Invoice missing", status: "open" },
  { id: 2, title: "Change delivery address", status: "closed" },
  { id: 3, title: "Login problem", status: "open" }
];

function App() {
  const [tickets, setTickets] = React.useState(() => INITIAL_TICKETS.map((ticket) => ({ ...ticket })));
  const [filter, setFilter] = React.useState("all");
  const [title, setTitle] = React.useState("");
  const [error, setError] = React.useState("");

  const visibleTickets = tickets.filter((ticket) => {
    return filter === "all" || ticket.status === filter;
  });

  function closeTicket(id) {
    setTickets((current) =>
      current.map((ticket) =>
        ticket.id === id ? { ...ticket, status: "closed" } : ticket
      )
    );
  }

  function createTicket(event) {
    event.preventDefault();
    const trimmed = title.trim();

    if (trimmed.length < 5) {
      setError("Title must be at least 5 characters");
      return;
    }

    setTickets((current) => {
      const nextId = current.reduce((max, ticket) => Math.max(max, ticket.id), 0) + 1;
      return [...current, { id: nextId, title: trimmed, status: "open" }];
    });
    setTitle("");
    setError("");
  }

  const openCount = tickets.filter((ticket) => ticket.status === "open").length;

  return (
    <main>
      <h1>Tickets</h1>

      <label>
        Status filter
        <select
          aria-label="Status filter"
          value={filter}
          onChange={(event) => setFilter(event.target.value)}
        >
          <option value="all">all</option>
          <option value="open">open</option>
          <option value="closed">closed</option>
        </select>
      </label>

      <ul aria-label="Tickets">
        {visibleTickets.map((ticket) => (
          <li key={ticket.id}>
            {ticket.title} ({ticket.status})
            {ticket.status === "open" && (
              <button type="button" onClick={() => closeTicket(ticket.id)}>
                Close
              </button>
            )}
          </li>
        ))}
      </ul>

      <form onSubmit={createTicket}>
        <input
          aria-label="New ticket title"
          value={title}
          onChange={(event) => setTitle(event.target.value)}
        />
        <button type="submit">Create</button>
      </form>

      {error && <p role="alert">{error}</p>}
      <p data-testid="open-count">{openCount} open</p>
    </main>
  );
}

