const list = document.querySelector('[aria-label="Tickets"]');
if (!list) throw new Error("Tickets list missing");
const text = list.textContent;
if (!text.includes("Invoice missing (open)")) throw new Error("Missing invoice ticket");
if (!text.includes("Change delivery address (closed)")) throw new Error("Missing address ticket");
if (!text.includes("Login problem (open)")) throw new Error("Missing login ticket");
if (document.querySelector('[data-testid="open-count"]').textContent.trim() !== "2 open") throw new Error("Wrong initial open count");
return true;

const select = document.querySelector('[aria-label="Status filter"]');
select.value = "closed";
select.dispatchEvent(new Event("change", { bubbles: true }));
await tick(0);
const list = document.querySelector('[aria-label="Tickets"]');
if (!list.textContent.includes("Change delivery address (closed)")) throw new Error("Closed ticket missing");
if (list.textContent.includes("Invoice missing (open)")) throw new Error("Open ticket should be filtered out");
if (list.textContent.includes("Login problem (open)")) throw new Error("Open ticket should be filtered out");
return true;

const buttons = [...document.querySelectorAll('[aria-label="Tickets"] button')];
if (buttons.length !== 2) throw new Error("Expected two Close buttons");
await click(buttons[0]);
const list = document.querySelector('[aria-label="Tickets"]');
if (!list.textContent.includes("Invoice missing (closed)")) throw new Error("Ticket was not closed");
if (list.querySelectorAll("button").length !== 1) throw new Error("Closed ticket still has a Close button");
if (document.querySelector('[data-testid="open-count"]').textContent.trim() !== "1 open") throw new Error("Open count was not updated");
return true;

const input = document.querySelector('[aria-label="New ticket title"]');
const create = [...document.querySelectorAll("button")].find((button) => button.textContent.trim() === "Create");
await typeInto(input, " abc ");
await click(create);
const alert = document.querySelector('[role="alert"]');
if (!alert || alert.textContent.trim() !== "Title must be at least 5 characters") throw new Error("Expected validation message");
if (document.querySelector('[aria-label="Tickets"]').textContent.includes("abc (open)")) throw new Error("Invalid ticket was added");
return true;

const input = document.querySelector('[aria-label="New ticket title"]');
const create = [...document.querySelectorAll("button")].find((button) => button.textContent.trim() === "Create");
await typeInto(input, "  Need help  ");
await click(create);
const list = document.querySelector('[aria-label="Tickets"]');
if (!list.textContent.includes("Need help (open)")) throw new Error("New ticket missing");
if (input.value !== "") throw new Error("Input was not cleared");
if (document.querySelector('[role="alert"]')) throw new Error("Validation alert was not removed");
if (document.querySelector('[data-testid="open-count"]').textContent.trim() !== "3 open") throw new Error("Open count was not updated");
return true;

const input = document.querySelector('[aria-label="New ticket title"]');
const create = [...document.querySelectorAll("button")].find((button) => button.textContent.trim() === "Create");
await typeInto(input, "Payment issue");
await click(create);
const find = () => [...document.querySelectorAll('[aria-label="Tickets"] li')].find((item) => item.textContent.includes("Payment issue"));
const newItem = find();
if (!newItem) throw new Error("New ticket not found");
if (!newItem.textContent.includes("Payment issue (open)")) throw new Error("New ticket should be open");
const items = [...document.querySelectorAll('[aria-label="Tickets"] li')];
if (items[items.length - 1] !== newItem) throw new Error("New ticket should be added to the end");
const closeButton = newItem.querySelector("button");
if (!closeButton) throw new Error("New ticket should have a Close button");
await click(closeButton);
const after = find();
if (!after || !after.textContent.includes("Payment issue (closed)")) throw new Error("Closing the new ticket should close only that ticket (it needs its own unique id)");
const count = document.querySelector('[data-testid="open-count"]').textContent.trim();
if (count !== "2 open") throw new Error("Expected 2 open, got " + count);
return true;

const input = document.querySelector('[aria-label="New ticket title"]');
const create = [...document.querySelectorAll("button")].find((button) => button.textContent.trim() === "Create");
await typeInto(input, "x");
await click(create);
if (!document.querySelector('[role="alert"]')) throw new Error("Expected alert");
await typeInto(input, "Valid title");
await click(create);
if (document.querySelector('[role="alert"]')) throw new Error("Alert should be removed after successful create");
return true;

const select = document.querySelector('[aria-label="Status filter"]');
select.value = "open";
select.dispatchEvent(new Event("change", { bubbles: true }));
await tick(0);
const input = document.querySelector('[aria-label="New ticket title"]');
const create = [...document.querySelectorAll("button")].find((button) => button.textContent.trim() === "Create");
await typeInto(input, "New request");
await click(create);
const list = document.querySelector('[aria-label="Tickets"]');
if (!list.textContent.includes("New request (open)")) throw new Error("New open ticket should appear in open filter");
if (list.textContent.includes("Change delivery address (closed)")) throw new Error("Closed ticket should remain filtered out");
return true;
